package com.shortlinkx.controller;
import com.shortlinkx.analytics.*;import com.shortlinkx.entity.ShortUrl;import com.shortlinkx.service.ShortUrlService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.net.URI;
@RestController public class RedirectController{private final ShortUrlService service;private final ClickEventProducer producer;public RedirectController(ShortUrlService service,ClickEventProducer producer){this.service=service;this.producer=producer;}@GetMapping("/{code}")public ResponseEntity<Void> redirect(@PathVariable String code,HttpServletRequest req){ShortUrl u=service.resolve(code);String ua=req.getHeader("User-Agent");producer.publish(new ClickEventPayload(code,req.getRemoteAddr(),ua,req.getHeader("Referer"),device(ua),browser(ua),os(ua)));return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(u.getLongUrl())).build();}private String device(String ua){if(ua==null)return"unknown";String v=ua.toLowerCase();return v.contains("mobile")||v.contains("android")||v.contains("iphone")?"mobile":v.contains("tablet")||v.contains("ipad")?"tablet":"desktop";}private String browser(String ua){if(ua==null)return"unknown";String v=ua.toLowerCase();if(v.contains("edg"))return"edge";if(v.contains("chrome"))return"chrome";if(v.contains("firefox"))return"firefox";if(v.contains("safari"))return"safari";return"other";}private String os(String ua){if(ua==null)return"unknown";String v=ua.toLowerCase();if(v.contains("windows"))return"windows";if(v.contains("mac os"))return"macos";if(v.contains("android"))return"android";if(v.contains("iphone")||v.contains("ipad"))return"ios";if(v.contains("linux"))return"linux";return"other";}}
